@props(['member'])<article class="team-profile"><div class="portrait-wrap">@if($member->photograph)<img src="{{ asset($member->photograph) }}" alt="{{ $member->name }}, {{ $member->role }}" width="864" height="1080" loading="lazy">@else<div class="portrait-placeholder">{{ $member->name }}</div>@endif</div><div><p class="eyebrow">The people behind the purpose</p><h2>{{ $member->name }}</h2><p class="role">{{ $member->role }}</p><p>{{ $member->biography }}</p>@if($member->publish_contact)<div class="profile-contact">@if($member->email)<a href="mailto:{{ $member->email }}">{{ $member->email }}</a>@endif @if($member->phone)<a href="tel:{{ preg_replace('/[^+0-9]/', '', $member->phone) }}">{{ $member->phone }}</a>@endif @foreach($member->social_links ?? [] as $label => $url) @if(filter_var($url, FILTER_VALIDATE_URL) && in_array(parse_url($url, PHP_URL_SCHEME), ['http', 'https']))<a href="{{ $url }}" rel="noopener noreferrer">{{ $label }}</a>@endif @endforeach</div>@endif<a class="text-link" href="{{ route('contact') }}#consultation">Start a conversation <span aria-hidden="true">↗</span></a></div></article>